 /** Parse a URL query string. See README.md for the rules. */
 export function parseQuery(query: string): Query {
-  throw new Error("not implemented");
+  const result: Query = {};
+
+  const input = query.startsWith("?") ? query.slice(1) : query;
+  if (input === "") {
+    return result;
+  }
+
+  for (const pair of input.split("&")) {
+    if (pair === "") {
+      continue;
+    }
+
+    const equalsIndex = pair.indexOf("=");
+    const rawKey = equalsIndex === -1 ? pair : pair.slice(0, equalsIndex);
+    const rawValue = equalsIndex === -1 ? "" : pair.slice(equalsIndex + 1);
+
+    const key = decodeQueryPart(rawKey);
+    const value = decodeQueryPart(rawValue);
+
+    const existing = result[key];
+    if (existing === undefined) {
+      result[key] = value;
+    } else if (Array.isArray(existing)) {
+      existing.push(value);
+    } else {
+      result[key] = [existing, value];
+    }
+  }
+
+  return result;
 }
+
+function decodeQueryPart(part: string): string {
+  const withSpaces = part.replace(/\+/g, " ");
+
+  try {
+    return decodeURIComponent(withSpaces);
+  } catch {
+    return withSpaces;
+  }
+}
